import{_ as a,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2020-09-02","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-09-02","date":"2020-09-02T00:00:00.000Z","updated":"2020-09-04T00:00:00.000Z","tags":["Ceph","分布式存储","BlueStore","性能优化","OSD"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-09-02.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-09-02.md","lastUpdated":1780460162000}'),o={name:"posts/2020/Ceph_Performance_Meeting_2020-09-02.md"};function i(s,e,n,u,h,d){return l(),t("div",null,[...e[0]||(e[0]=[r('<h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><p>本次会议主要讨论了Ceph存储系统中的技术议题，涵盖了新的Pull Request（PR）、BlueStore性能优化、OSD CPU效率提升以及未来的改进方向。</p><h3 id="主要讨论议题" tabindex="-1">主要讨论议题 <a class="header-anchor" href="#主要讨论议题" aria-label="Permalink to &quot;主要讨论议题&quot;">​</a></h3><h4 id="_1-新的pull-request-pr" tabindex="-1">1. 新的Pull Request (PR) <a class="header-anchor" href="#_1-新的pull-request-pr" aria-label="Permalink to &quot;1. 新的Pull Request (PR)&quot;">​</a></h4><ul><li><strong>PR1</strong>：Josh的PR旨在加速Monitor中的caps和cap更新，Joao已进行评审，默认行为未改变，仅在特定情况下提供跳过解析的选项。</li><li><strong>PR2</strong>：修改OSD异步恢复最小开销的默认值，建议降低阈值以增加异步恢复，基于Red Hat内部测试，发现默认值100在某些RGW工作负载下导致大量异步恢复。</li></ul><h4 id="_2-bluestore性能优化" tabindex="-1">2. BlueStore性能优化 <a class="header-anchor" href="#_2-bluestore性能优化" aria-label="Permalink to &quot;2. BlueStore性能优化&quot;">​</a></h4><ul><li>讨论了BlueStore在处理大量对象创建和删除时的性能瓶颈，特别是使用RocksDB时的解析和锁定问题。</li><li>提出了使用更大缓冲区减少写放大和尝试将部分数据移出RocksDB的建议。</li></ul><h4 id="_3-osd-cpu效率提升" tabindex="-1">3. OSD CPU效率提升 <a class="header-anchor" href="#_3-osd-cpu效率提升" aria-label="Permalink to &quot;3. OSD CPU效率提升&quot;">​</a></h4><ul><li>讨论了如何减少OSD的CPU使用，特别是在处理大量小对象时的效率问题。</li><li>提出了从字符串操作转向二进制格式操作的建议，以减少动态内存分配和提高比较效率。</li></ul><h4 id="_4-未来改进方向" tabindex="-1">4. 未来改进方向 <a class="header-anchor" href="#_4-未来改进方向" aria-label="Permalink to &quot;4. 未来改进方向&quot;">​</a></h4><ul><li>讨论了可能的硬件优化，如使用Optane DIMMs，以及软件层面的改进，如简化数据结构和减少不必要的灵活性。</li><li>提出了对BlueStore和OSD进行更深入的性能分析和优化，特别是在处理小对象和频繁更新的场景。</li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>继续探讨和实验BlueStore的性能优化，特别是在减少RocksDB的使用和优化OSD的CPU效率方面。</li><li>计划在下一次会议中进一步讨论OSD的内存使用优化和BlueStore的结构简化。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>更新现有文档，总结本次会议的讨论点和未来研究方向。</li><li>准备下一次会议的讨论主题，包括具体的性能优化实验和可能的技术改进。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议为Ceph存储系统的未来发展提供了宝贵的讨论和建议，特别是在性能优化和CPU效率提升方面。期待下一次会议的进一步讨论和成果。</p><p>请注意，原始字幕内容中包含了一些技术细节和讨论，这些内容在总结中并未全部体现，但已尽量保留关键信息。</p>',18)])])}const _=a(o,[["render",i]]);export{p as __pageData,_ as default};
